// Object.keys(groups) 的顺序决定 V4 不稳定排序里同 time 的键怎么排，要照 JS 还原：
// 数组下标形式的键（"0"、"42"，小于 2^32 - 1）按数值升序在前，其余键按插入顺序。
// groups 出自 groupsForList，插入顺序是各 appName 在传入列表里首次出现的顺序，也就是每组 notifications[0]
// 的先后；传入的列表是 list 或它的子序列 popupList，所以按 notifications[0] 在 list 里的位置排。
// 用 peek()：JS 版本只依赖 groups，不依赖 list。
const std::vector<::ii::services::Notifications_Notif*>& all = this->list.peek();
const auto position = [&all](const NotifGroup& group) {
  return group.notifications.empty()
             ? all.size()
             : static_cast<std::size_t>(std::find(all.begin(), all.end(), group.notifications.front()) - all.begin());
};
const auto arrayIndex = [](const std::string& key) -> std::optional<std::uint64_t> {
  if (key.empty() || key.size() > 10 || (key.size() > 1 && key[0] == '0')) {
    return std::nullopt;
  }
  std::uint64_t value = 0;
  for (const char c : key) {
    if (c < '0' || c > '9') {
      return std::nullopt;
    }
    value = value * 10 + static_cast<std::uint64_t>(c - '0');
  }
  return value < 4294967295ULL ? std::optional<std::uint64_t>(value) : std::nullopt;
};
std::vector<std::string> keys;
std::vector<std::string> named;
for (const auto& entry : groups) {
  (arrayIndex(entry.first) ? keys : named).push_back(entry.first);
}
std::sort(keys.begin(), keys.end(), [&](const std::string& a, const std::string& b) { return *arrayIndex(a) < *arrayIndex(b); });
std::stable_sort(named.begin(), named.end(), [&](const std::string& a, const std::string& b) {
  return position(groups.at(a)) < position(groups.at(b));
});
keys.insert(keys.end(), named.begin(), named.end());
return js::sorted(std::move(keys), [&groups](const std::string& a, const std::string& b) {
  // Sort by time, descending
  return groups.at(b).time - groups.at(a).time;
});

