// ii: JS 原地修改 latestTimeForApp，不发 latestTimeForAppChanged。QML 按连接顺序先运行这个处理函数，
// 再重新求值 groupsByAppName 等绑定，它们读到新的时间；runtime 里绑定先于 changed() 处理函数求值，
// 所以这里用 set() 通知，让依赖它的绑定再求值一次，最终结果与 QML 相同
std::map<std::string, double> latestTimes = this->latestTimeForApp.get();
const std::vector<::ii::services::Notifications_Notif*>& notifs = this->list.get();
// Update latest time for each app
for (::ii::services::Notifications_Notif* notif : notifs) {
  const std::string& appName = notif->appName.get();
  const double time = notif->time.get();
  const auto latest = latestTimes.find(appName);
  // !latestTimeForApp[appName]：没有这个键（undefined）或值为 0、NaN
  const bool unset = latest == latestTimes.end() || latest->second == 0 || std::isnan(latest->second);
  if (unset || time > latest->second) {
    // Math.max(latestTimeForApp[appName] || 0, notif.time)，有 NaN 时得 NaN
    const double current = unset ? 0.0 : latest->second;
    latestTimes[appName] = std::isnan(time) ? js::NaN : std::max(current, time);
  }
}
// Remove apps that no longer have notifications
for (auto entry = latestTimes.begin(); entry != latestTimes.end();) {
  const std::string& appName = entry->first;
  if (!js::some(notifs, [&appName](::ii::services::Notifications_Notif* notif) { return notif->appName.get() == appName; })) {
    entry = latestTimes.erase(entry);
  } else {
    ++entry;
  }
}
this->latestTimeForApp.set(std::move(latestTimes));

